-- Generated by scripts/build_compiled.py from src/fraudrules/rules/foreign-agent/fa-002-third-party-alert-jurisdictions.yaml. Do not edit.
-- FA-002 Agent regularly directs third-party payments to the jurisdictions the alert names
SELECT
  'FA-002' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.directing_agent_id = a.directing_agent_id
  AND b.ts <= a.ts
  AND b.ts > a.ts - 2592000
WHERE
  (
    a.direction = 'out'
    AND NOT a.directing_agent_id IS NULL
    AND a.in_agent_agreement = 0
    AND a.counterparty_country IN ('cn', 'ae', 'eg', 'ke', 'ug', 'dj')
  )
  AND (
    b.direction = 'out'
    AND NOT b.directing_agent_id IS NULL
    AND b.in_agent_agreement = 0
    AND b.counterparty_country IN ('cn', 'ae', 'eg', 'ke', 'ug', 'dj')
  )
GROUP BY
  a.id
HAVING
  COUNT(*) >= 3;
